<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\StudyPlanComplianceService;
class SpecialtyCurriculumController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$plans=DB::table('specialty_curricula as c')->join('specialties as sp','sp.id','=','c.specialty_id')->join('academic_years as ay','ay.id','=','c.academic_year_id')->select('c.*','sp.code','sp.name as specialty_name','ay.name as year_name')->orderByDesc('c.id')->get();$specialties=DB::table('specialties')->orderBy('code')->get();return view('academic-office.curricula',compact('plans','specialties','p'));}
 public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['specialty_id'=>'required|exists:specialties,id','name'=>'required|string|max:255']);$id=DB::table('specialty_curricula')->insertGetId(['specialty_id'=>$d['specialty_id'],'academic_year_id'=>$p->academic_year_id,'name'=>$d['name'],'version'=>1,'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('study-plan.show',$id);}
 public function show(Request $r,$id){$this->ok($r);$c=DB::table('specialty_curricula as c')->join('specialties as sp','sp.id','=','c.specialty_id')->where('c.id',$id)->select('c.*','sp.code','sp.name as specialty_name')->first();abort_if(!$c,404);$items=DB::table('specialty_curriculum_items as i')->join('subjects as s','s.id','=','i.subject_id')->leftJoin('study_types as st','st.id','=','i.study_type_id')->where('i.specialty_curriculum_id',$id)->select('i.*','s.name as subject_name','st.name as study_type_name')->orderBy('i.course')->orderBy('i.semester')->orderBy('i.component_code')->orderBy('s.name')->get();$subjects=DB::table('subjects')->orderBy('name')->get();$types=DB::table('study_types')->orderBy('name')->get();$period=$r->attributes->get('academic_period');$comparison=$period?(new StudyPlanComplianceService)->rows($c,$period,$items):collect();return view('academic-office.curriculum-show',compact('c','items','subjects','types','period','comparison'));}
 public function item(Request $r,$id){$this->ok($r);$c=DB::table('specialty_curricula')->find($id);abort_if(!$c,404);abort_if($c->status==='approved',423,'Утверждённый учебный план защищён.');$d=$r->validate(['course'=>'required|integer|min:1|max:6','semester'=>'required|integer|min:1|max:20','component_type'=>'required|in:discipline,professional_module,mdk,practice','component_code'=>'nullable|string|max:50','cycle_name'=>'nullable|string|max:255','subject_id'=>'required|exists:subjects,id','study_type_id'=>'nullable|exists:study_types,id','hours_total'=>'required|numeric|min:.1|max:9999','lecture_hours'=>'nullable|numeric|min:0|max:9999','practice_hours'=>'nullable|numeric|min:0|max:9999','lab_hours'=>'nullable|numeric|min:0|max:9999','self_study_hours'=>'nullable|numeric|min:0|max:9999','hours_week'=>'nullable|numeric|min:0|max:999','control_type'=>'nullable|string|max:100','has_exam'=>'nullable|boolean','has_credit'=>'nullable|boolean','has_differentiated_credit'=>'nullable|boolean','note'=>'nullable|string|max:2000']);
$d['has_exam']=$r->boolean('has_exam');$d['has_credit']=$r->boolean('has_credit');$d['has_differentiated_credit']=$r->boolean('has_differentiated_credit');
$detail=(float)($d['lecture_hours']??0)+(float)($d['practice_hours']??0)+(float)($d['lab_hours']??0)+(float)($d['self_study_hours']??0);
abort_if($detail>(float)$d['hours_total']+0.001,422,'Сумма видов часов не может превышать общее количество часов.');
DB::table('specialty_curriculum_items')->insert($d+['specialty_curriculum_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Дисциплина добавлена в учебный план.');}
 public function approve(Request $r,$id){$this->ok($r);$items=DB::table('specialty_curriculum_items')->where('specialty_curriculum_id',$id)->get();abort_if($items->isEmpty(),422,'Нельзя утвердить пустой учебный план.');foreach($items as $x){$detail=(float)$x->lecture_hours+(float)$x->practice_hours+(float)$x->lab_hours+(float)$x->self_study_hours;abort_if($detail>(float)$x->hours_total+0.001,422,'В учебном плане есть строка, где сумма видов часов превышает общий объём.');}DB::table('specialty_curricula')->where('id',$id)->update(['status'=>'approved','approved_by'=>$r->user()->id,'approved_at'=>now(),'updated_at'=>now()]);return back()->with('success','Учебный план проверен и утверждён.');}
 public function deploy(Request $r,$id){$this->ok($r);$p=$r->attributes->get('academic_period');$c=DB::table('specialty_curricula')->find($id);abort_if(!$c,404);abort_unless($c->status==='approved',422,'Сначала утвердите учебный план.');$groups=DB::table('study_groups')->where(['specialty_id'=>$c->specialty_id,'active'=>1])->get();$items=DB::table('specialty_curriculum_items')->where(['specialty_curriculum_id'=>$id,'semester'=>$p->number])->get();DB::transaction(function()use($groups,$items,$p,$r){foreach($groups as $g)foreach($items as $i){DB::table('load_requirements')->updateOrInsert(['academic_period_id'=>$p->id,'study_group_id'=>$g->id,'subject_id'=>$i->subject_id,'study_type_id'=>$i->study_type_id],['required_hours'=>$i->hours_total,'source'=>'study_plan','created_at'=>now(),'updated_at'=>now()]);if(!DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id,'subject_id'=>$i->subject_id])->exists())DB::table('curriculum_plans')->insert(['academic_period_id'=>$p->id,'study_group_id'=>$g->id,'subject_id'=>$i->subject_id,'teacher_id'=>null,'title'=>'Рабочая программа','status'=>'active','version'=>1,'approval_status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);}});return redirect()->route('tarification.index')->with('success','Потребность и заготовки рабочих программ созданы из учебного плана.');}
}